import{_ as t,o as a,c as r,a6 as i}from"./chunks/framework.BV_S2lHy.js";const o="/hivedocs/images/aruco-cell-assembly.png",b=JSON.parse('{"title":"ArUco cell","description":"Print and assemble the HiveBoard ArUco cell for board localization, physical-to-simulation alignment, and dataset collection.","frontmatter":{"description":"Print and assemble the HiveBoard ArUco cell for board localization, physical-to-simulation alignment, and dataset collection."},"headers":[],"relativePath":"hardware/aruco-cell.md","filePath":"hardware/aruco-cell.md","lastUpdated":1790391539000}'),n={name:"hardware/aruco-cell.md"};function s(l,e,d,c,h,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="aruco-cell" tabindex="-1">ArUco cell <a class="header-anchor" href="#aruco-cell" aria-label="Permalink to &quot;ArUco cell&quot;">​</a></h1><p>The ArUco cell provides a visual reference for locating HiveBoard in camera images. Its estimated pose can be used to place the board in a robot coordinate frame or align a simulated scene with a physical setup.</p><p>The cell is an optional accessory. Benchmark evaluations still contain <strong>13 conditions with five trials each</strong>.</p><figure class="doc-image"><img src="'+o+'" alt="CAD view of the ArUco cell, with a white hexagonal base and black marker insert" width="530"><figcaption>Assembly model. The white base and black insert are printed separately and fitted together.</figcaption></figure><h2 id="files-and-materials" tabindex="-1">Files and materials <a class="header-anchor" href="#files-and-materials" aria-label="Permalink to &quot;Files and materials&quot;">​</a></h2><p>Download the files from <a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/CAD/ArUco%20Cell" target="_blank" rel="noreferrer"><code>CAD/ArUco Cell/</code></a>.</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th><th>Filament</th></tr></thead><tbody><tr><td><code>aruco_cell_base_white.obj</code></td><td>Hexagonal base and white marker regions</td><td>White PLA</td></tr><tr><td><code>aruco_cell_marker_black.obj</code></td><td>Black marker insert</td><td>Black PLA</td></tr><tr><td><code>aruco_cell_assembly.obj</code></td><td>Reference model showing both parts in position</td><td>—</td></tr></tbody></table><p>Keep each OBJ beside its matching MTL file. MTL files specify display colors. Select the filament separately in the slicer. Print the base and insert as separate parts.</p><h2 id="dimensions-and-import-scale" tabindex="-1">Dimensions and import scale <a class="header-anchor" href="#dimensions-and-import-scale" aria-label="Permalink to &quot;Dimensions and import scale&quot;">​</a></h2><p>The OBJ coordinates correspond to centimetres. Set the import units or scale explicitly.</p><table tabindex="0"><thead><tr><th>Quantity</th><th>Value</th></tr></thead><tbody><tr><td>Overall width</td><td>88.1 mm</td></tr><tr><td>Assembly bounding box</td><td>88.1 × 76.297 × 22.0 mm</td></tr><tr><td>Nominal outer black square</td><td>47.505 mm per side</td></tr><tr><td>Import into a millimetre-based application</td><td>Multiply coordinates by 10</td></tr><tr><td>Import into a metre-based simulator</td><td>Multiply coordinates by 0.01</td></tr></tbody></table><p>Apply the same scale to both parts. Confirm the assembled width before printing. For pose estimation, measure the printed marker from the outer edges of its black square. Use that measured side length in the detector.</p><h2 id="print-and-assemble" tabindex="-1">Print and assemble <a class="header-anchor" href="#print-and-assemble" aria-label="Permalink to &quot;Print and assemble&quot;">​</a></h2><ol><li>Import the base and insert with the scale specified above.</li><li>Print the base in white PLA and the insert in black PLA. Use the <a href="/hivedocs/hardware/printing#printer-requirements">PLA printing settings</a> as a starting point.</li><li>Remove stringing and excess material from the mating surfaces.</li><li>Fit the insert into the base, following the assembly model. Check that it is fully seated and the marker face is complete.</li><li>For permanent assembly, apply a small amount of PLA-compatible adhesive to the mating surfaces. Keep adhesive off the marker face and allow it to cure.</li><li>Seat the cell in the honeycomb base. Choose a position visible to the camera that leaves the required task cells available and the robot&#39;s approach clear.</li></ol><p>Check that the cell remains fixed during manipulation. Recheck its pose relative to the board after moving or reseating it.</p><h2 id="marker-and-camera-configuration" tabindex="-1">Marker and camera configuration <a class="header-anchor" href="#marker-and-camera-configuration" aria-label="Permalink to &quot;Marker and camera configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Setting</th></tr></thead><tbody><tr><td>OpenCV dictionary</td><td><code>DICT_4X4_50</code></td></tr><tr><td>Marker ID</td><td><code>0</code></td></tr><tr><td>Marker side length</td><td>Measured outer black-square side, in the units used for pose estimation</td></tr></tbody></table><p>The marker was created with <a href="https://chev.me/arucogen/" target="_blank" rel="noreferrer">chev.me/arucogen</a> using <strong>4×4 (50, 100, 250, 1000)</strong> and <strong>ID 0</strong>. This ID has the same pattern in the four standard OpenCV 4×4 dictionaries. Use <code>DICT_4X4_50</code> for a consistent detector configuration.</p><p>Calibrate the camera at the resolution used for detection and retain its intrinsic parameters and distortion coefficients. Verify detection of ID 0 on the printed cell at the intended working distance and viewing angles. Check that the marker remains visible under the experiment&#39;s lighting conditions.</p><p>Pose estimation also requires the marker&#39;s position and orientation relative to the chosen board frame. To express the board pose in robot coordinates, obtain the camera pose in that coordinate frame. For a moving camera, use the camera pose corresponding to the image timestamp.</p><p>See the <a href="https://docs.opencv.org/4.x/d5/dae/tutorial_aruco_detection.html" target="_blank" rel="noreferrer">OpenCV ArUco documentation</a> for detection and pose estimation.</p><h2 id="physical-to-simulation-alignment" tabindex="-1">Physical-to-simulation alignment <a class="header-anchor" href="#physical-to-simulation-alignment" aria-label="Permalink to &quot;Physical-to-simulation alignment&quot;">​</a></h2><p>Import the assembly mesh with the correct scale and place it relative to the same board frame used in the physical setup. Use the measured marker-to-board transform when converting a detected marker pose into a board pose.</p><p>Check the resulting alignment at known points on the board before using it for robot motion or comparing trajectories. Record the coordinate-frame conventions, camera calibration, and marker-to-board transform. The cell provides a reference for geometric alignment. Physical parameter identification is described in <a href="/hivedocs/simulation/assets#physical-parameters">Simulation assets</a>.</p><h2 id="record-with-a-dataset" tabindex="-1">Record with a dataset <a class="header-anchor" href="#record-with-a-dataset" aria-label="Permalink to &quot;Record with a dataset&quot;">​</a></h2><p>When using the cell during <a href="/hivedocs/guides/datahive">DataHive collection</a>, retain:</p><ul><li>the camera images and timestamps used for detection;</li><li>camera intrinsics, distortion coefficients, and camera-to-robot calibration when used;</li><li>the dictionary, marker ID, and measured marker side length;</li><li>the marker-to-board transform and coordinate-frame definitions;</li><li>any estimated poses, with their timestamps and detection failures.</li></ul><p>Keep these calibration records with the session metadata. Agree on supplemental files with the organizers if they fall outside the current DataHive episode format. Installing DataHive does not configure marker detection or board-pose estimation.</p><p>For benchmark evaluations, record the localization method in the platform description and continue to record each trial with an external camera.</p>',29)])])}const u=t(n,[["render",s]]);export{b as __pageData,u as default};
